-- ROPOWER 사채 어드민 V7 · 레거시 DB/수임인/실입금 재파싱
-- 기준: 사용자 제공 3개 원본 텍스트 파일
-- 핵심: DB 메모/담당자/현황 이관, 성공보수→환수, 실제 입금일/입금액 정산 연동, 레거시 경고 제외, 기술 메모 제거
-- 이 스크립트는 기존 운영 데이터를 전체 삭제하지 않습니다. 이전 ROPOWER_LEGACY_IMPORT 계열 이관 레코드만 교체/정리합니다.

begin;

-- 안전 확인: 로파워 Supabase 계정/스키마인지 검사
do $$
begin
  if to_regclass('public.customers') is null or to_regclass('public.meta_leads') is null or to_regclass('public.payment_schedules') is null then
    raise exception 'ROPOWER safety check failed: required tables are missing.';
  end if;
  if not exists (
    select 1 from auth.users
    where lower(coalesce(email,'')) in ('shk@1.com','wndgh1245@naver.com','doublestone@1.com','hsw@1.com')
  ) then
    raise exception 'ROPOWER safety check failed: expected ROPOWER auth users were not found. Supabase 프로젝트를 확인하세요.';
  end if;
end $$;

-- 1) 레거시 이관 플래그
alter table public.customers add column if not exists legacy_imported boolean not null default false;
alter table public.recoveries add column if not exists legacy_imported boolean not null default false;
create index if not exists customers_legacy_imported_idx on public.customers(legacy_imported) where deleted_at is null;

-- 2) 정산 자동연동 메모를 사람이 보는 메모만 남기도록 정리
create or replace function public.sync_payment_schedule_to_settlement()
returns trigger
language plpgsql
security definer
set search_path=public
as $$
declare
  v_payment_id uuid;
  v_customer_id uuid;
  v_customer_name text;
  v_status text;
  v_paid_date date;
  v_paid_amount numeric;
  v_payment_method text;
  v_schedule_type text;
  v_payment_memo text;
  v_deleted_at timestamptz;
  v_settlement_id uuid;
  v_should_create boolean := false;
  v_type text;
  v_memo text;
begin
  if tg_op = 'DELETE' then
    v_payment_id := old.id;
    update public.settlement_entries
       set deleted_at = coalesce(deleted_at, now())
     where source_payment_schedule_id = v_payment_id
       and deleted_at is null;
    return old;
  end if;

  v_payment_id := new.id;
  v_customer_id := new.customer_id;
  v_status := coalesce(new.status,'');
  v_paid_date := new.paid_date;
  v_paid_amount := coalesce(new.paid_amount,0);
  v_payment_method := coalesce(nullif(new.payment_method,''),'계좌이체');
  v_schedule_type := coalesce(nullif(new.schedule_type,''),'일반');
  v_payment_memo := btrim(coalesce(new.memo,''));
  v_deleted_at := new.deleted_at;

  select id into v_settlement_id
    from public.settlement_entries
   where source_payment_schedule_id = v_payment_id
   limit 1;

  if v_settlement_id is not null then
    if v_deleted_at is not null or v_status <> '완료' or v_paid_date is null or v_paid_amount <= 0 then
      update public.settlement_entries
         set deleted_at = coalesce(deleted_at, now())
       where id = v_settlement_id;
      return new;
    end if;
    v_should_create := true;
  else
    if tg_op = 'INSERT' then
      v_should_create := v_deleted_at is null and v_status='완료' and v_paid_date is not null and v_paid_amount>0;
    elsif tg_op = 'UPDATE' then
      v_should_create := old.status is distinct from '완료'
        and v_deleted_at is null and v_status='완료' and v_paid_date is not null and v_paid_amount>0;
    end if;
  end if;

  if not v_should_create then return new; end if;

  select name into v_customer_name from public.customers where id=v_customer_id limit 1;
  v_type := case when v_schedule_type='환수' then '환수' else '계약' end;
  v_memo := v_payment_memo;

  if v_settlement_id is null then
    insert into public.settlement_entries(
      payment_date,client_name,amount,payment_method,memo,
      customer_id,source_payment_schedule_id,entry_source,entry_type,deleted_at
    ) values (
      v_paid_date,coalesce(v_customer_name,''),v_paid_amount,v_payment_method,v_memo,
      v_customer_id,v_payment_id,'payment',v_type,null
    );
  else
    update public.settlement_entries
       set payment_date=v_paid_date,
           client_name=coalesce(v_customer_name,''),
           amount=v_paid_amount,
           payment_method=v_payment_method,
           memo=v_memo,
           customer_id=v_customer_id,
           entry_source='payment',
           entry_type=v_type,
           deleted_at=null
     where id=v_settlement_id;
  end if;
  return new;
end;
$$;

-- 3) 과거 성공보수(legacy_imported=true)는 환수 목록에는 보존하되 실제 현금은 아래 실입금 원장으로만 정산
create or replace function public.sync_recovery_payment()
returns trigger
language plpgsql
set search_path=public
as $$
declare
  v_payment_id uuid;
  v_memo text;
begin
  select id into v_payment_id
  from public.payment_schedules
  where source_recovery_id=new.id
  order by admin_created_at desc nulls last
  limit 1;

  if new.deleted_at is not null then
    if v_payment_id is not null then
      update public.payment_schedules set deleted_at=coalesce(deleted_at,now()) where id=v_payment_id;
    end if;
    return new;
  end if;

  if coalesce(new.legacy_imported,false) then
    if v_payment_id is not null then
      update public.payment_schedules set deleted_at=coalesce(deleted_at,now()) where id=v_payment_id;
    end if;
    return new;
  end if;

  v_memo := btrim(coalesce(new.memo,''));

  if v_payment_id is null then
    insert into public.payment_schedules(
      customer_id,due_date,expected_amount,paid_date,paid_amount,status,payment_method,memo,
      schedule_type,reschedule_sequence,source_recovery_id
    ) values (
      new.customer_id,new.recovery_date,new.amount,new.recovery_date,new.amount,'완료',new.payment_method,v_memo,
      '환수',0,new.id
    );
  else
    update public.payment_schedules
       set customer_id=new.customer_id,
           due_date=new.recovery_date,
           expected_amount=new.amount,
           paid_date=new.recovery_date,
           paid_amount=new.amount,
           status='완료',
           payment_method=new.payment_method,
           memo=v_memo,
           schedule_type='환수',
           deleted_at=null
     where id=v_payment_id;
  end if;
  return new;
end;
$$;

-- 4) 이관 중 기간별 변동내역 로그 폭주 방지
do $$
begin
  if exists(select 1 from pg_trigger where tgrelid='public.customers'::regclass and tgname='trg_change_history_customers' and not tgisinternal) then
    execute 'alter table public.customers disable trigger trg_change_history_customers';
  end if;
  if exists(select 1 from pg_trigger where tgrelid='public.payment_schedules'::regclass and tgname='trg_change_history_payments' and not tgisinternal) then
    execute 'alter table public.payment_schedules disable trigger trg_change_history_payments';
  end if;
  if exists(select 1 from pg_trigger where tgrelid='public.settlement_entries'::regclass and tgname='trg_change_history_settlements' and not tgisinternal) then
    execute 'alter table public.settlement_entries disable trigger trg_change_history_settlements';
  end if;
  if exists(select 1 from pg_trigger where tgrelid='public.additional_contracts'::regclass and tgname='trg_change_history_additional_contracts' and not tgisinternal) then
    execute 'alter table public.additional_contracts disable trigger trg_change_history_additional_contracts';
  end if;
end $$;

-- 5) 예전 ROPOWER_LEGACY_IMPORT 이관 산출물만 정리 (일반 운영 데이터는 보존)
update public.customers set legacy_imported=true where coalesce(memo,'') like '%ROPOWER_LEGACY_IMPORT%';
update public.recoveries set legacy_imported=true where coalesce(memo,'') like '%ROPOWER_LEGACY_IMPORT%';
update public.additional_contracts set deleted_at=coalesce(deleted_at,now()) where deleted_at is null and coalesce(memo,'') like '%ROPOWER_LEGACY_IMPORT%';
update public.recoveries set deleted_at=coalesce(deleted_at,now()) where deleted_at is null and coalesce(memo,'') like '%ROPOWER_LEGACY_IMPORT%';
update public.payment_schedules set deleted_at=coalesce(deleted_at,now()) where deleted_at is null and coalesce(memo,'') like '%ROPOWER_LEGACY_IMPORT%';

-- 6) 수임인 원본 재파싱
create temp table tmp_legacy_clients(
  stage_key text primary key,
  source_row integer not null,
  deterministic_id uuid not null,
  registered_at date,
  admin_created_at timestamptz,
  name text not null,
  phone text not null,
  manager text not null,
  memo text not null,
  contract_amount numeric not null,
  installment_period integer not null,
  lender_unit_price numeric not null,
  lender_count integer not null,
  eformsign_status text not null
) on commit drop;
