create temp table tmp_legacy_customer_map(
  stage_key text primary key,
  customer_id uuid not null
) on commit drop;

insert into tmp_legacy_customer_map(stage_key,customer_id)
select s.stage_key,c.id
from tmp_legacy_clients s
join lateral (
  select x.id
  from public.customers x
  where x.deleted_at is null
    and (
      (s.phone<>'' and regexp_replace(coalesce(x.phone,''),'[^0-9]','','g')=regexp_replace(s.phone,'[^0-9]','','g'))
      or coalesce(x.memo,'') like ('%원본 행 '||s.source_row::text||']%')
      or (s.phone='' and btrim(coalesce(x.name,''))=btrim(s.name))
    )
  order by
    case when coalesce(x.memo,'') like ('%원본 행 '||s.source_row::text||']%') then 0
         when s.phone<>'' and regexp_replace(coalesce(x.phone,''),'[^0-9]','','g')=regexp_replace(s.phone,'[^0-9]','','g') then 1
         else 2 end,
    x.admin_created_at asc nulls last,
    x.id
  limit 1
) c on true
on conflict(stage_key) do nothing;

insert into public.customers(
  id,registered_at,admin_created_at,name,phone,address,birth_number,
  manager,sales_manager,coordination_manager,memo,contract_date,contract_amount,
  upfront_amount,installment_period,lender_unit_price,lender_count,
  is_accident,eformsign_status,legacy_imported
)
select
  s.deterministic_id,s.registered_at,coalesce(s.admin_created_at,now()),s.name,s.phone,null,null,
  s.manager,s.manager,s.manager,s.memo,s.registered_at,s.contract_amount,
  0,s.installment_period,s.lender_unit_price,s.lender_count,
  false,nullif(s.eformsign_status,''),true
from tmp_legacy_clients s
left join tmp_legacy_customer_map m on m.stage_key=s.stage_key
where m.customer_id is null
on conflict(id) do update set
  deleted_at=null,
  legacy_imported=true;

insert into tmp_legacy_customer_map(stage_key,customer_id)
select s.stage_key,s.deterministic_id
from tmp_legacy_clients s
where not exists(select 1 from tmp_legacy_customer_map m where m.stage_key=s.stage_key)
on conflict(stage_key) do nothing;

update public.customers c
set registered_at=s.registered_at,
    name=s.name,
    phone=case when s.phone<>'' then s.phone else coalesce(c.phone,'') end,
    manager=s.manager,
    sales_manager=s.manager,
    coordination_manager=s.manager,
    memo=s.memo,
    contract_date=s.registered_at,
    contract_amount=s.contract_amount,
    upfront_amount=0,
    installment_period=s.installment_period,
    lender_unit_price=s.lender_unit_price,
    lender_count=s.lender_count,
    legacy_imported=true,
    eformsign_status=case when s.eformsign_status<>'' then s.eformsign_status else c.eformsign_status end,
    deleted_at=null
from tmp_legacy_clients s
join tmp_legacy_customer_map m on m.stage_key=s.stage_key
where c.id=m.customer_id;

-- 7) 동일 수임인의 후속/추가 수임행 → 추가계약
create temp table tmp_legacy_additional(
  id uuid primary key,stage_key text not null,source_row integer not null,contract_date date,
  contract_amount numeric not null,installment_period integer not null,lender_unit_price numeric not null,
  lender_count integer not null,memo text not null
) on commit drop;
