insert into public.additional_contracts(
  id,customer_id,contract_date,contract_amount,upfront_amount,installment_period,lender_unit_price,lender_count,memo,deleted_at
)
select a.id,m.customer_id,a.contract_date,a.contract_amount,0,a.installment_period,a.lender_unit_price,a.lender_count,a.memo,null
from tmp_legacy_additional a join tmp_legacy_customer_map m using(stage_key)
on conflict(id) do update set
  customer_id=excluded.customer_id,contract_date=excluded.contract_date,contract_amount=excluded.contract_amount,
  upfront_amount=0,installment_period=excluded.installment_period,lender_unit_price=excluded.lender_unit_price,
  lender_count=excluded.lender_count,memo=excluded.memo,deleted_at=null;

