insert into public.recoveries(
  id,customer_id,recovery_date,lender_name,recovery_type,amount,payment_method,memo,legacy_imported,deleted_at
)
select r.id,m.customer_id,r.recovery_date,'','성공보수',r.amount,'계좌이체',r.memo,true,null
from tmp_legacy_recoveries r join tmp_legacy_customer_map m using(stage_key)
on conflict(id) do update set
  customer_id=excluded.customer_id,recovery_date=excluded.recovery_date,lender_name='',
  recovery_type='성공보수',amount=excluded.amount,payment_method='계좌이체',
  memo=excluded.memo,legacy_imported=true,deleted_at=null;

