insert into public.payment_schedules(
  id,customer_id,due_date,expected_amount,paid_date,paid_amount,status,payment_method,memo,
  schedule_type,reschedule_sequence,admin_created_at,deleted_at
)
select
  p.id,m.customer_id,p.paid_date,p.paid_amount,p.paid_date,p.paid_amount,'완료',p.payment_method,'',
  p.schedule_type,0,(p.paid_date::timestamp + interval '12 hours' + (p.source_row % 300) * interval '1 second') at time zone 'Asia/Seoul',null
from tmp_legacy_payments p
join tmp_legacy_customer_map m using(stage_key)
where (
  select count(*)
  from public.payment_schedules x
  where x.customer_id=m.customer_id
    and x.deleted_at is null
    and x.status='완료'
    and x.paid_date=p.paid_date
    and coalesce(x.paid_amount,0)=p.paid_amount
    and coalesce(nullif(x.payment_method,''),'계좌이체')=p.payment_method
    and coalesce(nullif(x.schedule_type,''),'일반')=p.schedule_type
) < p.duplicate_rank
on conflict(id) do update set
  customer_id=excluded.customer_id,due_date=excluded.due_date,expected_amount=excluded.expected_amount,
  paid_date=excluded.paid_date,paid_amount=excluded.paid_amount,status='완료',
  payment_method=excluded.payment_method,memo='',schedule_type=excluded.schedule_type,deleted_at=null;

-- 10) 과거 DB: 메모 / 담당자 / 현황을 현재 드롭다운 값으로 매핑
-- 매핑: 수임→전환, 재통화/보류중→재연락, 부재중→부재중, 고려중→상담중, 거절→유효리드, 중복/없는번호→허수
-- SQL 이관은 Meta API를 호출하지 않으므로 과거 상태를 광고계정으로 재전송하지 않습니다.
create temp table tmp_legacy_leads(
  id uuid primary key,source_row bigint not null,created_at timestamptz,name text not null,phone text not null,
  manager text not null,lender_count integer not null,memo text not null,collection_intensity text not null,
  principal_amount text not null,repayment_total text not null,evidence text not null,third_party_damage text not null,
  lead_result text not null,customer_stage_key text
) on commit drop;
