do $$
declare
  r record;
  v_existing_id uuid;
  v_customer_id uuid;
begin
  for r in select * from tmp_legacy_leads order by source_row loop
    v_existing_id := null;
    v_customer_id := null;

    select ml.id into v_existing_id
    from public.meta_leads ml
    where ml.source_row_number=r.source_row
       or ml.meta_lead_id=('legacy-db-v7:'||r.source_row::text)
    order by case when ml.source_row_number=r.source_row then 0 else 1 end, ml.created_at desc
    limit 1;

    if v_existing_id is null then
      select ml.id into v_existing_id
      from public.meta_leads ml
      where r.phone<>''
        and regexp_replace(coalesce(ml.phone_number,''),'[^0-9]','','g')=regexp_replace(r.phone,'[^0-9]','','g')
        and ml.created_at::date=r.created_at::date
      order by ml.created_at desc
      limit 1;
    end if;

    if r.customer_stage_key is not null then
      select m.customer_id into v_customer_id
      from tmp_legacy_customer_map m
      where m.stage_key=r.customer_stage_key;
    end if;

    if v_existing_id is null then
      insert into public.meta_leads(
        id,meta_lead_id,created_at,customer_name,phone_number,
        manager,sales_manager,coordination_manager,lender_count,memo,
        collection_intensity,principal_amount,repayment_total,evidence,third_party_damage,
        lead_result,status,customer_id,converted_at,source_row_number
      ) values (
        r.id,'legacy-db-v7:'||r.source_row::text,r.created_at,r.name,r.phone,
        r.manager,r.manager,r.manager,r.lender_count,r.memo,
        r.collection_intensity,r.principal_amount,r.repayment_total,r.evidence,r.third_party_damage,
        r.lead_result,
        case when v_customer_id is not null then '고객등록완료' else '신규' end,
        v_customer_id,
        case when v_customer_id is not null then r.created_at else null end,
        r.source_row
      );
    else
      update public.meta_leads
      set created_at=coalesce(r.created_at,created_at),
          customer_name=case when r.name<>'' then r.name else customer_name end,
          phone_number=case when r.phone<>'' then r.phone else phone_number end,
          manager=case when r.manager<>'미지정' then r.manager else manager end,
          sales_manager=case when r.manager<>'미지정' then r.manager else sales_manager end,
          coordination_manager=case when r.manager<>'미지정' then r.manager else coordination_manager end,
          lender_count=case when r.lender_count>0 then r.lender_count else lender_count end,
          memo=case when r.memo<>'' then r.memo else memo end,
          collection_intensity=case when r.collection_intensity<>'' then r.collection_intensity else collection_intensity end,
          principal_amount=case when r.principal_amount<>'' then r.principal_amount else principal_amount end,
          repayment_total=case when r.repayment_total<>'' then r.repayment_total else repayment_total end,
          evidence=case when r.evidence<>'' then r.evidence else evidence end,
          third_party_damage=case when r.third_party_damage<>'' then r.third_party_damage else third_party_damage end,
          lead_result=case when coalesce(lead_result,'미분류')='미분류' then r.lead_result else lead_result end,
          status=case when status='고객등록완료' or customer_id is not null or v_customer_id is not null then '고객등록완료' else '신규' end,
          customer_id=coalesce(customer_id,v_customer_id),
          converted_at=case when status='고객등록완료' or customer_id is not null or v_customer_id is not null then coalesce(converted_at,r.created_at) else converted_at end,
          source_row_number=coalesce(source_row_number,r.source_row)
      where id=v_existing_id;
    end if;
  end loop;
end $$;

-- 11) 화면에 보이던 기술용 마이그레이션 문구 제거
update public.settlement_entries
set memo=btrim(
  regexp_replace(
    regexp_replace(coalesce(memo,''),'^\[입금/분납 자동연동\]\s*(계약 입금|재약정|추가계약 선납|환수)?\s*(·\s*)?','','i'),
    '^\[ROPOWER_LEGACY_IMPORT_V[0-9]+\][^\n]*?(·\s*)?','','i'
  )
)
where deleted_at is null
  and (coalesce(memo,'') like '[입금/분납 자동연동]%' or coalesce(memo,'') like '[ROPOWER_LEGACY_IMPORT%');
update public.payment_schedules
set memo=btrim(regexp_replace(coalesce(memo,''),'^\[ROPOWER_LEGACY_IMPORT_V[0-9]+\][^\n]*?(·\s*)?','','i'))
where deleted_at is null and coalesce(memo,'') like '[ROPOWER_LEGACY_IMPORT%';

-- 12) 기존 레거시 고객 메모에 남아있는 이관 헤더는 이번 원본 메모로 이미 교체됨

-- 13) 변동내역 트리거 복구
do $$
begin
  if exists(select 1 from pg_trigger where tgrelid='public.customers'::regclass and tgname='trg_change_history_customers' and not tgisinternal) then
    execute 'alter table public.customers enable trigger trg_change_history_customers';
  end if;
  if exists(select 1 from pg_trigger where tgrelid='public.payment_schedules'::regclass and tgname='trg_change_history_payments' and not tgisinternal) then
    execute 'alter table public.payment_schedules enable trigger trg_change_history_payments';
  end if;
  if exists(select 1 from pg_trigger where tgrelid='public.settlement_entries'::regclass and tgname='trg_change_history_settlements' and not tgisinternal) then
    execute 'alter table public.settlement_entries enable trigger trg_change_history_settlements';
  end if;
  if exists(select 1 from pg_trigger where tgrelid='public.additional_contracts'::regclass and tgname='trg_change_history_additional_contracts' and not tgisinternal) then
    execute 'alter table public.additional_contracts enable trigger trg_change_history_additional_contracts';
  end if;
end $$;

commit;

-- ===== 확인용 =====
select count(*) as legacy_customers from public.customers where deleted_at is null and legacy_imported=true;
select count(*) as legacy_leads from public.meta_leads where source_row_number between 2 and 498;
select count(*) as exact_completed_payments, coalesce(sum(paid_amount),0) as exact_payment_total
from public.payment_schedules p join public.customers c on c.id=p.customer_id
where p.deleted_at is null and c.legacy_imported=true and p.status='완료' and p.paid_date between '2026-05-01' and '2026-09-30';
select entry_type, count(*) as rows, coalesce(sum(amount),0) as total
from public.settlement_entries s join public.customers c on c.id=s.customer_id
where s.deleted_at is null and c.legacy_imported=true and s.payment_date between '2026-05-01' and '2026-09-30'
group by entry_type order by entry_type;

